insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_ushist_v1'
from (values
('113.41.d.1.A',3,'Which document states that governments get their power from the consent of the governed?','["the Declaration of Independence", "the Mayflower Compact", "the Articles of Confederation", "the Emancipation Proclamation"]'::jsonb,0,'The Declaration of Independence asserts consent of the governed.','original'),
('113.41.d.1.A',3,'Which principle in the U.S. Constitution divides power among the legislative, executive and judicial branches?','["nullification", "separation of powers", "manifest destiny", "divine right"]'::jsonb,1,'Separation of powers prevents concentration of authority.','original'),
('113.41.d.1.B',4,'The Fourteenth Amendment''s guarantee of equal protection was later used in cases such as Brown v. Board of Education. Which founding principle is applied?','["rule by hereditary leaders", "unlimited executive power", "equality under the law", "state religion"]'::jsonb,2,'Founding ideals were applied to later struggles for rights.','original'),
('113.41.d.1.C',2,'The national motto ''E Pluribus Unum'' is usually translated as what?','["freedom for all", "liberty and justice", "in God we trust", "out of many, one"]'::jsonb,3,'It expresses unity from diversity.','original'),
('113.41.d.2.A',3,'Which era of U.S. history is associated with industrialization, big business and immigration after Reconstruction?','["the Gilded Age", "the Colonial period", "the Jazz Age", "the Era of Good Feelings"]'::jsonb,0,'Industrial growth and inequality defined the Gilded Age.','original'),
('113.41.d.2.B',3,'Which year marks the start of the Spanish-American War?','["1877", "1898", "1914", "1941"]'::jsonb,1,'The war began in 1898.','original'),
('113.41.d.2.B',3,'Which event is the turning point of December 7, 1941?','["the sinking of the Maine", "the stock market crash", "the attack on Pearl Harbor", "the Cuban Missile Crisis"]'::jsonb,2,'It brought the United States into World War II.','original'),
('113.41.d.3.A',3,'What was the main purpose of the Pendleton Civil Service Act of 1883?','["to create a national bank", "to regulate railroads", "to ban immigration", "to base federal hiring on merit rather than political favors"]'::jsonb,3,'It reformed the spoils system.','original'),
('113.41.d.3.A',4,'Political machines like Tammany Hall gained power in cities by doing what?','["trading services and jobs for votes", "outlawing parties", "ending patronage", "banning elections"]'::jsonb,0,'Machines relied on patronage and immigrant votes.','original'),
('113.41.d.3.A',3,'The Dawes Act of 1887 sought to change American Indian life by doing what?','["granting each tribe full sovereignty", "dividing tribal lands into individual allotments", "creating new reservations on the coast", "ending all federal involvement"]'::jsonb,1,'It aimed to assimilate Indians through private land ownership.','original'),
('113.41.d.3.B',3,'Which law, passed in 1890, was designed to limit monopolies and trusts?','["the Homestead Act", "the Pendleton Act", "the Sherman Antitrust Act", "the Dawes Act"]'::jsonb,2,'It targeted anti-competitive combinations.','original'),
('113.41.d.3.B',3,'Which labor organization, led by Samuel Gompers, focused on skilled workers and workplace bargaining?','["the Knights of Labor", "the Grange", "the Populist Party", "the American Federation of Labor"]'::jsonb,3,'The AFL organized craft unions.','original'),
('113.41.d.3.B',3,'Farmers in the late 1800s formed the Grange to do what?','["address problems with railroad rates and prices", "support industrial monopolies", "ban machines", "increase tariffs on imports"]'::jsonb,0,'Farmers sought relief from high costs and low crop prices.','original'),
('113.41.d.3.C',3,'What was a major cause of rapid urban growth in the late 1800s?','["the end of railroads", "industrial jobs and immigration", "decline of factories", "a ban on migration"]'::jsonb,1,'Cities grew as workers arrived.','original'),
('113.41.d.3.C',4,'Settlement houses such as Hull House aimed to do what?','["train soldiers", "regulate banks", "help immigrants and the urban poor adjust to city life", "build railroads"]'::jsonb,2,'Jane Addams founded Hull House in Chicago.','original'),
('113.41.d.4.A',3,'Which event is often cited as a spark for the Spanish-American War?','["the Zimmermann Telegram", "the Boston Massacre", "the attack at Pearl Harbor", "the explosion of the USS Maine"]'::jsonb,3,'The Maine''s destruction in Havana inflamed public opinion.','original'),
('113.41.d.4.B',3,'As a result of the Spanish-American War, the United States gained which territory?','["the Philippines", "Texas", "Alaska", "Louisiana"]'::jsonb,0,'The Treaty of Paris transferred Spain''s Pacific territories.','original'),
('113.41.d.4.B',4,'What was the Open Door Policy toward China intended to ensure?','["Chinese isolation", "equal trading access for all nations", "a ban on trade", "U.S. control of China"]'::jsonb,1,'It aimed to prevent exclusive spheres of influence.','original'),
('113.41.d.4.C',3,'Which German action in 1917 helped push the United States into World War I?','["the Berlin Airlift", "the bombing of Pearl Harbor", "unrestricted submarine warfare", "the invasion of Poland"]'::jsonb,2,'U-boat attacks on shipping provoked the U.S.','original'),
('113.41.d.4.C',3,'The Zimmermann Telegram proposed what?','["a peace plan", "a U.S. treaty with France", "an arms agreement with Britain", "a German alliance with Mexico against the United States"]'::jsonb,3,'It alarmed Americans and contributed to the declaration of war.','original'),
('113.41.d.4.D',3,'Who commanded the American Expeditionary Forces in World War I?','["John J. Pershing", "Douglas MacArthur", "Dwight Eisenhower", "George Patton"]'::jsonb,0,'Pershing led U.S. forces in Europe.','original'),
('113.41.d.4.E',3,'Which new weapon of World War I spread poison gas across trenches and caused terrible suffering?','["nuclear submarines", "chemical warfare", "stealth aircraft", "atomic bombs"]'::jsonb,1,'Gas attacks were a new horror.','original'),
('113.41.d.4.E',3,'Trench warfare on the Western Front led to what?','["an early peace", "few deaths", "long stalemates and heavy casualties", "swift victories"]'::jsonb,2,'Machine guns made advances deadly.','original'),
('113.41.d.4.F',4,'Woodrow Wilson''s Fourteen Points included a proposal to create what?','["a U.N. Security Council", "the Marshall Plan", "NATO", "a League of Nations"]'::jsonb,3,'Wilson sought an international body to preserve peace.','original'),
('113.41.d.4.F',3,'Why did the U.S. Senate refuse to ratify the Treaty of Versailles?','["many senators feared it would draw the U.S. into foreign entanglements", "it banned all trade", "it gave the U.S. too little power", "it ended the war too early"]'::jsonb,0,'Isolationist sentiment blocked ratification.','original'),
('113.41.d.5.A',3,'Which Progressive Era reform lets voters propose laws directly?','["the veto", "the initiative", "the filibuster", "the impeachment"]'::jsonb,1,'Initiative, referendum and recall expanded direct democracy.','original'),
('113.41.d.5.A',3,'The Seventeenth Amendment changed U.S. Senate elections by doing what?','["creating a Senate veto", "giving states two more senators", "providing for direct election of senators by voters", "ending term limits"]'::jsonb,2,'It replaced election by state legislatures.','original'),
('113.41.d.5.B',3,'Upton Sinclair''s novel ''The Jungle'' led to reforms in what industry?','["textiles", "railroads", "banking", "meatpacking"]'::jsonb,3,'It exposed unsanitary conditions and prompted food safety laws.','original'),
('113.41.d.5.B',3,'Which muckraker investigated the Standard Oil Company in a series of magazine articles?','["Ida Tarbell", "Jacob Riis", "Booker T. Washington", "Margaret Sanger"]'::jsonb,0,'Tarbell exposed Standard Oil''s business practices.','original'),
('113.41.d.5.C',3,'The Populist Party of the 1890s mainly represented which group?','["railroad executives", "farmers", "bankers", "factory owners"]'::jsonb,1,'Populists pushed for farm relief and monetary change.','original'),
('113.41.d.5.C',4,'Theodore Roosevelt ran in 1912 under which third party?','["the Socialist Party", "the Populist Party", "the Progressive (Bull Moose) Party", "the Whig Party"]'::jsonb,2,'His candidacy split the Republican vote.','original'),
('113.41.d.6.A',3,'The Scopes Trial of 1925 centered on a conflict over what?','["women''s suffrage", "immigration quotas", "Prohibition", "teaching evolution in public schools"]'::jsonb,3,'It reflected tension between traditional and modern views.','original'),
('113.41.d.6.A',3,'Which constitutional amendment established Prohibition in 1920?','["the Eighteenth Amendment", "the Twenty-First Amendment", "the Nineteenth Amendment", "the Sixteenth Amendment"]'::jsonb,0,'It banned the manufacture and sale of alcohol.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_ushist_v1'
from (values
('113.41.d.6.A',3,'The Red Scare of 1919-1920 was fueled by fear of what?','["inflation", "communism and radicalism", "foreign trade", "railroad strikes only"]'::jsonb,1,'Post-war anxiety targeted suspected radicals.','original'),
('113.41.d.6.B',3,'Henry Ford''s assembly line helped make cars more affordable by doing what?','["banning mass manufacturing", "limiting production", "lowering production costs", "raising prices"]'::jsonb,2,'Efficiency made the Model T widely available.','original'),
('113.41.d.6.B',3,'Charles Lindbergh became a national hero in 1927 for what achievement?','["winning an election", "inventing the airplane", "founding a union", "flying solo nonstop across the Atlantic"]'::jsonb,3,'He flew from New York to Paris.','original'),
('113.41.d.7.A',3,'Which event directly brought the United States into World War II?','["Japan''s attack on Pearl Harbor", "the fall of Paris", "the sinking of the Lusitania", "the invasion of Poland"]'::jsonb,0,'The U.S. declared war the day after.','original'),
('113.41.d.7.A',3,'Which leaders headed the Axis powers'' aggression in Europe and Asia?','["Stalin, Churchill and Roosevelt", "Hitler, Mussolini and Tojo", "Lenin, Wilson and Chiang", "De Gaulle, Franco and Truman"]'::jsonb,1,'Germany, Italy and Japan were the Axis.','original'),
('113.41.d.7.B',3,'Franklin D. Roosevelt''s domestic leadership during the war included which action?','["disbanding the army", "cutting factory output", "mobilizing the economy for wartime production", "ending the draft"]'::jsonb,2,'The home front shifted to war industry.','original'),
('113.41.d.7.B',4,'Harry Truman''s decision in 1945 to use atomic weapons was intended to do what?','["prolong the conflict", "support Germany", "start the Cold War", "bring Japan''s surrender and end the war"]'::jsonb,3,'Truman aimed to end the war without a costly invasion.','original'),
('113.41.d.7.C',3,'Executive Order 9066 led to what policy during World War II?','["the internment of Japanese Americans", "the Marshall Plan", "rationing of gasoline", "the draft of women"]'::jsonb,0,'Thousands were relocated to camps.','original'),
('113.41.d.7.C',3,'The systematic murder of six million Jews by Nazi Germany is known as what?','["the Kristallnacht boycott", "the Holocaust", "the Anschluss", "the Blitz"]'::jsonb,1,'A genocide carried out by the Nazi regime.','original'),
('113.41.d.7.D',3,'The D-Day invasion of June 6, 1944 took place in which region?','["Guadalcanal", "Sicily, Italy", "Normandy, France", "Iwo Jima"]'::jsonb,2,'Allied forces landed on the beaches of Normandy.','original'),
('113.41.d.7.D',4,'The Battle of Midway was significant because it did what?','["ended the war in Europe", "began the Cold War", "led to the atomic bomb", "turned the tide of the war in the Pacific"]'::jsonb,3,'U.S. carriers sank four Japanese carriers.','original'),
('113.41.d.7.E',3,'Which general served as Supreme Allied Commander in Europe?','["Dwight Eisenhower", "Chester Nimitz", "Douglas MacArthur", "George Marshall"]'::jsonb,0,'Eisenhower led the D-Day invasion.','original'),
('113.41.d.7.E',3,'Which general famously pledged ''I shall return'' about the Philippines?','["George Patton", "Douglas MacArthur", "Mark Clark", "Omar Bradley"]'::jsonb,1,'MacArthur led the Pacific campaign.','original'),
('113.41.d.7.F',2,'Victory Gardens during World War II were planted to do what?','["recruit soldiers", "advertise war bonds", "supplement food supplies for the war effort", "teach geography"]'::jsonb,2,'Home gardens eased food shortages.','original'),
('113.41.d.7.F',3,'War bonds sold on the home front helped the government do what?','["pay off the Depression", "reduce taxes", "end rationing", "finance the war"]'::jsonb,3,'Citizens lent money to the government.','original'),
('113.41.d.7.G',3,'The Tuskegee Airmen are remembered for what?','["serving as Black military pilots in a segregated army", "leading D-Day", "inventing radar", "working at Los Alamos"]'::jsonb,0,'They proved their skill and courage.','original'),
('113.41.d.8.A',3,'The Truman Doctrine pledged U.S. support for which kind of nations?','["non-aligned neutral states only", "those resisting communist takeover", "Soviet allies", "colonial powers"]'::jsonb,1,'It underlay the policy of containment.','original'),
('113.41.d.8.A',3,'The Marshall Plan provided what to Western Europe?','["a currency union", "military conscripts", "economic aid for rebuilding after the war", "nuclear weapons"]'::jsonb,2,'It aimed to stabilize economies.','original'),
('113.41.d.8.A',3,'The Berlin Airlift (1948-1949) was a response to what?','["the Korean War", "the Cuban Missile Crisis", "the Suez Crisis", "a Soviet blockade of West Berlin"]'::jsonb,3,'Allies supplied the city by air.','original'),
('113.41.d.8.B',3,'Senator Joseph McCarthy became known for doing what?','["making sweeping accusations of communism in the government", "negotiating the Camp David Accords", "leading the Berlin Airlift", "writing the Marshall Plan"]'::jsonb,0,'McCarthyism spread fear and suspicion.','original'),
('113.41.d.8.C',3,'The United States entered the Korean War in 1950 mainly to do what?','["fight Vietnam", "defend South Korea against a communist invasion", "reclaim Japan", "support North Korea"]'::jsonb,1,'It reflected containment policy.','original'),
('113.41.d.8.D',4,'The domino theory held that if one country fell to communism, what would follow?','["a U.S. withdrawal", "Soviet collapse", "neighboring countries would also fall", "a global treaty"]'::jsonb,2,'It justified intervention in Southeast Asia.','original'),
('113.41.d.8.D',3,'The Cuban Missile Crisis of 1962 involved what?','["a Soviet attack on Berlin", "a coup in Chile", "a U.S. invasion of Korea", "Soviet nuclear missiles placed in Cuba"]'::jsonb,3,'Kennedy imposed a naval quarantine.','original'),
('113.41.d.8.E',3,'The 1968 Tet Offensive shook American confidence because it did what?','["showed the enemy could launch large attacks despite official optimism", "captured Washington", "ended the war immediately", "ended the draft"]'::jsonb,0,'It contradicted claims of progress.','original'),
('113.41.d.8.E',3,'What was President Nixon''s policy of ''Vietnamization''?','["escalating troops", "turning ground fighting over to South Vietnamese forces", "ending all aid", "invading Cambodia permanently"]'::jsonb,1,'It aimed to reduce U.S. combat roles.','original'),
('113.41.d.8.F',3,'The Twenty-sixth Amendment, ratified in 1971, did what?','["gave women the vote", "limited presidents to two terms", "lowered the voting age to 18", "banned poll taxes"]'::jsonb,2,'It was spurred by the argument that those old enough to fight could vote.','original'),
('113.41.d.8.F',3,'Television coverage of the Vietnam War affected public opinion by doing what?','["ending the draft", "hiding events", "boosting enlistment sharply", "bringing images of combat into American homes"]'::jsonb,3,'Media coverage shaped views of the war.','original'),
('113.41.d.9.A',3,'Which 1896 Supreme Court decision upheld ''separate but equal''?','["Plessy v. Ferguson", "Brown v. Board of Education", "Marbury v. Madison", "Gideon v. Wainwright"]'::jsonb,0,'It legalized segregation.','original'),
('113.41.d.9.B',3,'Jim Crow laws in the South did what?','["ended segregation", "enforced racial segregation", "expanded voting rights", "banned lynching"]'::jsonb,1,'They separated people by race.','original'),
('113.41.d.9.C',3,'Which organization, founded in 1909, worked to end racial discrimination through legal action?','["the AFL", "the KKK", "the NAACP", "SNCC"]'::jsonb,2,'The NAACP pursued litigation and advocacy.','original'),
('113.41.d.9.C',3,'Cesar Chavez organized which group of workers?','["steelworkers", "railroad engineers", "miners", "farm workers"]'::jsonb,3,'He cofounded the United Farm Workers.','original'),
('113.41.d.9.D',3,'Which leader promoted nonviolent protest, citing Gandhi''s influence?','["Martin Luther King Jr.", "Marcus Garvey", "Stokely Carmichael", "Malcolm X"]'::jsonb,0,'King led marches and boycotts.','original'),
('113.41.d.9.D',3,'Who refused to give up her seat on a Montgomery bus in 1955?','["Ruby Bridges", "Rosa Parks", "Fannie Lou Hamer", "Harriet Tubman"]'::jsonb,1,'It sparked the Montgomery bus boycott.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_ushist_v1'
from (values
('113.41.d.9.E',4,'How did the Black Panthers'' approach differ from Dr. King''s?','["it rejected all protest", "it supported segregation", "it emphasized self-defense and community empowerment rather than strict nonviolence", "it relied only on the courts"]'::jsonb,2,'The groups differed in tactics.','original'),
('113.41.d.9.F',3,'Dr. King''s ''Letter from Birmingham Jail'' responded to criticism of what?','["his book sales", "his campaign for governor", "his service in the army", "his nonviolent direct-action protests"]'::jsonb,3,'He defended civil disobedience against unjust laws.','original'),
('113.41.d.9.G',3,'The Civil Rights Act of 1964 outlawed what?','["discrimination in public places and employment", "literacy tests only", "poll taxes only", "school desegregation only"]'::jsonb,0,'It banned many forms of discrimination.','original'),
('113.41.d.9.G',3,'The Voting Rights Act of 1965 aimed to do what?','["ban all segregation in housing", "protect the right of Black citizens to vote", "end the draft", "create Medicare"]'::jsonb,1,'It targeted discriminatory voting practices.','original'),
('113.41.d.9.H',4,'Governor Orval Faubus of Arkansas resisted integration in 1957 by doing what?','["resigning", "closing the state", "calling out the National Guard to block Black students from Central High", "supporting integration"]'::jsonb,2,'Eisenhower sent federal troops.','original'),
('113.41.d.9.I',3,'Which change resulted from the civil rights movement?','["a ban on protest", "a return of segregation", "the end of the Constitution", "increased political participation by African Americans"]'::jsonb,3,'Voting and officeholding expanded.','original'),
('113.41.d.9.J',3,'Brown v. Board of Education (1954) declared what?','["segregated public schools unconstitutional", "the draft illegal", "segregated trains legal", "poll taxes legal"]'::jsonb,0,'It overturned ''separate but equal'' in schools.','original'),
('113.41.d.9.J',4,'Sweatt v. Painter (1950) helped lay the groundwork for Brown by showing what?','["states controlled all schooling", "separate law schools could not be truly equal", "integration was optional", "segregation was equal"]'::jsonb,1,'It undermined the separate-but-equal doctrine.','original'),
('113.41.d.10.A',3,'Nixon''s 1972 visit to China was important because it did what?','["ended the Cold War", "started the Korean War", "began normalizing relations between the two countries", "created NATO"]'::jsonb,2,'It shifted Cold War diplomacy.','original'),
('113.41.d.10.A',3,'Détente refers to what?','["a space program", "a trade embargo", "a military alliance", "a relaxation of tensions between the superpowers"]'::jsonb,3,'Détente reduced Cold War tension in the 1970s.','original'),
('113.41.d.10.B',3,'Reagan''s economic program, sometimes called supply-side economics, emphasized what?','["tax cuts and reduced regulation", "nationalizing industry", "price controls", "higher taxes"]'::jsonb,0,'It aimed to spur growth.','original'),
('113.41.d.10.B',3,'President Reagan''s Strategic Defense Initiative proposed what?','["a new draft", "a missile defense system", "a space station", "a trade treaty"]'::jsonb,1,'Nicknamed ''Star Wars'' by critics.','original'),
('113.41.d.10.C',3,'The Camp David Accords of 1978 involved which two countries?','["Syria and Jordan", "Iran and Iraq", "Egypt and Israel", "Saudi Arabia and Turkey"]'::jsonb,2,'Carter brokered a peace framework.','original'),
('113.41.d.10.C',3,'The Iran hostage crisis began in 1979 when militants did what?','["sank a warship", "invaded Kuwait", "bombed Pearl Harbor", "seized the U.S. embassy in Tehran"]'::jsonb,3,'Americans were held for 444 days.','original'),
('113.41.d.10.D',4,'The Heritage Foundation and the Moral Majority are associated with which trend of the 1980s?','["the conservative resurgence", "the New Deal", "the Populist revolt", "the Progressive movement"]'::jsonb,0,'Conservative groups gained influence.','original'),
('113.41.d.10.E',3,'The War on Drugs of the 1980s aimed to do what?','["legalize narcotics", "reduce drug trafficking and use through tougher enforcement", "ban pharmacies", "end all prisons"]'::jsonb,1,'It increased penalties and enforcement.','original'),
('113.41.d.11.A',3,'The Cold War is generally considered to have ended with what event?','["the Cuban Missile Crisis", "the Korean War", "the collapse of the Soviet Union", "Pearl Harbor"]'::jsonb,2,'The USSR dissolved in 1991.','original'),
('113.41.d.11.A',3,'The Persian Gulf War (1991) began when Iraq did what?','["bombed Saudi Arabia", "seized Iran", "attacked Israel", "invaded Kuwait"]'::jsonb,3,'A U.S.-led coalition liberated Kuwait.','original'),
('113.41.d.11.A',3,'The terrorist attacks of September 11, 2001 led to which U.S. response?','["the war in Afghanistan and the creation of the Department of Homeland Security", "a return to isolationism", "the end of NATO", "a new draft only"]'::jsonb,0,'The attacks reshaped U.S. foreign and domestic policy.','original'),
('113.41.d.11.C',4,'Third-party candidate Ross Perot in 1992 mattered because he did what?','["won the presidency", "drew a significant share of the popular vote", "won the House", "withdrew before the election"]'::jsonb,1,'He won about 19 percent.','original'),
('113.41.d.11.C',3,'In the 2000 election, Ralph Nader''s third-party campaign is often cited for its impact in which state?','["Alaska", "California", "Florida", "Texas"]'::jsonb,2,'The close Florida margin was decisive.','original'),
('113.41.d.13.A',3,'The Great Migration refers to the movement of African Americans from where to where?','["the Midwest to the Pacific", "the North to the South", "Mexico to the East", "the rural South to Northern and Midwestern cities"]'::jsonb,3,'Millions left for jobs and opportunity.','original'),
('113.41.d.13.A',3,'Which postwar trend led many Americans to move toward the Sun Belt?','["air conditioning and job growth", "ending of highways", "decline of defense jobs", "colder weather"]'::jsonb,0,'The South and West grew.','original'),
('113.41.d.13.B',3,'Immigration to the U.S. increased after 1965 because the Immigration and Nationality Act did what?','["reduced visas to zero", "ended national-origins quotas", "banned all immigration", "limited entry to Europeans"]'::jsonb,1,'It opened immigration from Asia and Latin America.','original'),
('113.41.d.13.B',3,'Ellis Island served as what?','["a prison", "a military fort", "an immigration station in New York Harbor", "a trading post"]'::jsonb,2,'Millions entered the U.S. there.','original'),
('113.41.d.14.B',3,'The Environmental Protection Agency was created in 1970 to do what?','["build highways", "manage the postal service", "regulate banks", "enforce federal environmental regulations"]'::jsonb,3,'Established under Nixon.','original'),
('113.41.d.14.B',3,'The Dust Bowl was worsened by what practice?','["plowing up grasslands without soil conservation", "rotating crops", "building canals", "planting trees"]'::jsonb,0,'Drought plus poor practices caused massive erosion.','original'),
('113.41.d.14.A',3,'Rapid population growth in cities often leads to which environmental effect?','["cleaner rivers", "increased air and water pollution", "lower traffic", "more forests"]'::jsonb,1,'Growth strains the environment.','original'),
('113.41.d.15.A',3,'The Homestead Act of 1862 encouraged settlement of the West by doing what?','["taxing land", "banning farming", "offering land to settlers who farmed it", "giving land to railroads only"]'::jsonb,2,'It spurred migration to the Plains.','original'),
('113.41.d.15.A',3,'The Transcontinental Railroad was completed in what year?','["1909", "1849", "1889", "1869"]'::jsonb,3,'The tracks joined at Promontory Summit.','original'),
('113.41.d.15.B',3,'Interstate Commerce Act of 1887 aimed to do what?','["regulate railroad rates", "ban labor unions", "limit immigration", "create the Federal Reserve"]'::jsonb,0,'It created the first federal regulatory commission.','original'),
('113.41.d.15.C',3,'The Chinese Exclusion Act of 1882 did what?','["created Angel Island", "barred Chinese laborers from entering the country", "welcomed Chinese immigrants", "ended the railroad"]'::jsonb,1,'It was the first major law restricting immigration by nationality.','original'),
('113.41.d.15.D',3,'How did World War I affect the U.S. economy?','["it caused a depression", "it eliminated debt", "it boosted industrial production and made the U.S. a creditor nation", "it ended manufacturing"]'::jsonb,2,'Wartime demand increased output.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_ushist_v1'
from (values
('113.41.d.16.A',3,'A major cause of 1920s prosperity was what?','["a ban on credit", "a decline in production", "high unemployment", "growth in consumer goods and the automobile industry"]'::jsonb,3,'Mass production fueled growth.','original'),
('113.41.d.16.A',3,'Calvin Coolidge''s approach to the economy in the 1920s was characterized by what?','["limited government and low taxes", "heavy regulation", "nationalization", "public works spending"]'::jsonb,0,'Business-friendly policies defined the era.','original'),
('113.41.d.16.B',3,'Which event is commonly associated with the start of the Great Depression?','["the Marshall Plan", "the stock market crash of 1929", "the Dust Bowl", "the Spanish-American War"]'::jsonb,1,'The crash exposed fragile financial conditions.','original'),
('113.41.d.16.B',4,'Buying stocks on margin contributed to the crash because it did what?','["required full cash payment", "made stocks safer", "let investors borrow to buy stocks, magnifying losses when prices fell", "banned speculation"]'::jsonb,2,'Debt-financed speculation increased risk.','original'),
('113.41.d.16.C',3,'Unemployment during the Great Depression reached about what level?','["one in ten thousand", "one in fifty", "none", "one in four workers"]'::jsonb,3,'About 25 percent were unemployed at the worst.','original'),
('113.41.d.16.D',3,'The New Deal programs aimed to bring what?','["relief, recovery and reform", "higher tariffs only", "ending government", "isolation only"]'::jsonb,0,'The three Rs summarize the New Deal.','original'),
('113.41.d.16.E',3,'The Federal Deposit Insurance Corporation (FDIC) was created to do what?','["plant trees", "insure bank deposits", "hire artists", "build dams"]'::jsonb,1,'It restored faith in banks.','original'),
('113.41.d.16.E',3,'The Social Security Act of 1935 created a system for what?','["school desegregation", "interstate highways", "retirement and unemployment support", "food rationing"]'::jsonb,2,'It established old-age pensions.','original'),
('113.41.d.16.E',3,'The Tennessee Valley Authority (TVA) brought what to the rural South?','["telephone monopolies", "free schooling", "new state governments", "electricity and flood control"]'::jsonb,3,'It built dams and power plants.','original'),
('113.41.d.17.A',3,'World War II helped end the Great Depression by doing what?','["boosting production and creating jobs", "cutting factories", "ending trade", "raising unemployment"]'::jsonb,0,'War mobilization restored full employment.','original'),
('113.41.d.17.B',3,'The GI Bill after World War II helped veterans by doing what?','["ending the draft", "providing education and home-loan benefits", "taxing wages", "banning unions"]'::jsonb,1,'It helped fuel postwar prosperity.','original'),
('113.41.d.17.B',3,'The Baby Boom contributed to 1950s prosperity by doing what?','["reducing school needs", "ending suburbs", "increasing demand for homes and goods", "lowering consumption"]'::jsonb,2,'More families meant more consumption.','original'),
('113.41.d.17.C',4,'President Eisenhower warned in 1961 about the influence of what?','["the Federal Reserve", "labor unions", "the free press", "the military-industrial complex"]'::jsonb,3,'His farewell address cautioned about defense spending.','original'),
('113.41.d.17.E',3,'NAFTA, enacted in the 1990s, was designed to do what?','["reduce trade barriers among the U.S., Canada and Mexico", "tax imports", "create a currency union", "ban trade with Mexico"]'::jsonb,0,'It expanded North American trade.','original'),
('113.41.d.18.A',3,'President Franklin Roosevelt''s ''court-packing'' plan in 1937 was an attempt to do what?','["end judicial review", "add justices to the Supreme Court to gain support for New Deal laws", "create a new branch", "remove the Court"]'::jsonb,1,'It was widely criticized and failed.','original'),
('113.41.d.18.B',3,'Executive Order 9066 raised constitutional questions about what?','["the census", "the right to bear arms", "civil liberties during wartime", "the electoral college"]'::jsonb,2,'Internment tested due process rights.','original'),
('113.41.d.18.C',3,'The Watergate scandal led to what?','["a Supreme Court vacancy", "a second term for Nixon", "a presidential impeachment trial of Reagan", "the resignation of President Nixon"]'::jsonb,3,'Nixon resigned in 1974.','original'),
('113.41.d.18.C',3,'The Teapot Dome scandal involved what?','["bribery over oil reserves under Harding", "a war declaration", "Prohibition", "a stock crash"]'::jsonb,0,'Government officials took bribes for leases.','original'),
('113.41.d.18.D',3,'The Americans with Disabilities Act (1990) prohibits what?','["labor strikes", "discrimination against people with disabilities", "taxation", "immigration"]'::jsonb,1,'It guarantees access and equal opportunity.','original'),
('113.41.d.19.A',4,'The Gulf of Tonkin Resolution of 1964 gave the president authority to do what?','["withdraw troops", "end the draft", "use military force in Vietnam without a formal declaration of war", "declare war on China"]'::jsonb,2,'It later prompted debate about war powers.','original'),
('113.41.d.19.A',4,'The War Powers Act of 1973 requires the president to do what?','["get approval from the Court", "end all deployments", "obtain a UN vote", "notify Congress soon after committing troops abroad"]'::jsonb,3,'Congress sought to check presidential war-making.','original'),
('113.41.d.19.B',3,'Marbury v. Madison established which principle?','["judicial review", "implied powers", "states'' rights", "executive privilege"]'::jsonb,0,'Courts can strike down unconstitutional laws.','original'),
('113.41.d.20.A',3,'In Miranda v. Arizona (1966) the Court ruled that police must do what?','["keep records secret", "inform suspects of their rights before questioning", "release all suspects", "stop all interrogations"]'::jsonb,1,'The ''Miranda warning'' stems from this case.','original'),
('113.41.d.20.A',3,'Gideon v. Wainwright guaranteed what for defendants?','["free speech", "the right to remain silent only", "the right to an attorney in felony cases", "the right to a jury of peers only"]'::jsonb,2,'States must provide counsel for the poor.','original'),
('113.41.d.20.A',3,'In Roe v. Wade (1973) the Court recognized what?','["school prayer", "campaign finance", "a ban on abortion", "a constitutional right to privacy covering abortion decisions"]'::jsonb,3,'The decision was later overturned in Dobbs v. Jackson (2022).','original'),
('113.41.d.20.B',3,'The Sixteenth Amendment gave Congress the power to do what?','["levy an income tax", "abolish slavery", "grant women the vote", "ban alcohol"]'::jsonb,0,'It was ratified in 1913.','original'),
('113.41.d.20.B',3,'The Nineteenth Amendment guaranteed what?','["a federal income tax", "women''s suffrage", "direct election of senators", "the end of Prohibition"]'::jsonb,1,'Ratified in 1920.','original'),
('113.41.d.21.A',3,'Which value is central to a constitutional republic?','["rule by one person", "censorship", "the rule of law", "inherited rank"]'::jsonb,2,'Laws bind both citizens and leaders.','original'),
('113.41.d.21.B',3,'American values like individualism and free enterprise contrast with societies that emphasize what?','["voting rights", "free speech", "private property", "strict state control of the economy"]'::jsonb,3,'The U.S. system differs from command economies.','original'),
('113.41.d.22.A',3,'Lobbying is an effort to do what?','["influence lawmakers on a particular issue", "count votes", "write a constitution", "draft recruits"]'::jsonb,0,'Groups petition officials.','original'),
('113.41.d.22.B',3,'The Twenty-fourth Amendment banned what?','["literacy tests", "poll taxes in federal elections", "primary elections", "the electoral college"]'::jsonb,1,'It removed a barrier used to suppress votes.','original'),
('113.41.d.22.D',3,'Which step is required to become a naturalized citizen?','["paying a bond", "serving in office", "passing a civics and English test", "buying property"]'::jsonb,2,'Applicants must show knowledge of civics and English.','original'),
('113.41.d.23.A',3,'Andrew Carnegie is associated with which industry?','["oil", "banking", "railroads", "steel"]'::jsonb,3,'He founded Carnegie Steel.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
