from (values
('113.41.d.23.A',3,'John D. Rockefeller built a fortune in which industry?','["oil", "steel", "textiles", "automobiles"]'::jsonb,0,'He founded Standard Oil.','original'),
('113.41.d.23.B',3,'The Congressional Medal of Honor recognizes what?','["athletic achievement", "extraordinary bravery in combat", "scientific discoveries", "political donations"]'::jsonb,1,'It is the nation''s highest military decoration.','original'),
('113.41.d.24.B',3,'The Harlem Renaissance was a flowering of what?','["colonial settlement", "factory production", "African American art, music and literature", "labor unions"]'::jsonb,2,'It centered in New York in the 1920s.','original'),
('113.41.d.24.B',3,'Which music genre emerged from African American communities in New Orleans in the early 1900s?','["country", "punk", "disco", "jazz"]'::jsonb,3,'Jazz shaped American culture.','original'),
('113.41.d.24.C',3,'Hollywood movies and American music helped do what?','["spread American culture around the world", "limit trade", "isolate the U.S.", "end radio"]'::jsonb,0,'Media spread U.S. culture globally.','original'),
('113.41.d.25.A',3,'The women''s suffrage movement worked to expand what?','["tariffs", "voting rights for women", "military draft", "property taxes"]'::jsonb,1,'Activists won the vote in 1920.','original'),
('113.41.d.25.B',3,'American Indian boarding schools of the late 1800s were designed to do what?','["preserve tribal languages", "prepare for statehood", "assimilate Native children into mainstream culture", "teach tribal law"]'::jsonb,2,'Americanization efforts sought to erase tribal identity.','original'),
('113.41.d.25.D',3,'Sonia Sotomayor became the first Latina to serve on what?','["the U.S. Senate", "the Cabinet", "the Federal Reserve", "the U.S. Supreme Court"]'::jsonb,3,'She was appointed in 2009.','original'),
('113.41.d.26.A',3,'Thomas Edison''s work contributed to the spread of what?','["electric lighting and power", "the telephone", "the radio", "the steam engine"]'::jsonb,0,'He developed practical electric lighting systems.','original'),
('113.41.d.26.A',3,'Alexander Graham Bell is credited with inventing what?','["the radio", "the telephone", "the television", "the telegraph"]'::jsonb,1,'Patented in 1876.','original'),
('113.41.d.26.C',3,'Assembly line manufacturing changed the workplace by doing what?','["ending wages", "ending factories", "dividing tasks to speed production", "banning machinery"]'::jsonb,2,'Workers repeated specialized tasks.','original'),
('113.41.d.27.A',3,'The Space Race between the U.S. and the Soviet Union began after the Soviets launched what?','["Vostok 5", "Apollo 11", "Skylab", "Sputnik"]'::jsonb,3,'The 1957 satellite startled Americans.','original'),
('113.41.d.27.A',3,'Which mission first landed humans on the Moon?','["Apollo 11", "Gemini 3", "Mercury 7", "Apollo 1"]'::jsonb,0,'Neil Armstrong and Buzz Aldrin landed in 1969.','original'),
('113.41.d.27.B',3,'The free enterprise system drives innovation by doing what?','["taxing all profit", "rewarding profitable new ideas", "banning competition", "setting prices by law"]'::jsonb,1,'Competition and profit motivate invention.','original'),
('113.41.d.28.A',3,'A political cartoon from 1900 shows a giant octopus labeled ''Standard Oil.'' What is it most likely criticizing?','["the weather", "farm prices", "the power of monopolies", "foreign tariffs"]'::jsonb,2,'The octopus symbolizes grasping control.','original'),
('113.41.d.28.B',3,'Placing the Civil Rights Act of 1964 before the Voting Rights Act of 1965 on a timeline is an example of what?','["averaging dates", "ignoring order", "mapping boundaries", "sequencing events chronologically"]'::jsonb,3,'Chronology orders events by time.','original'),
('113.41.d.28.D',3,'A diary written during the Dust Bowl by a farmer is what kind of source?','["a primary source", "a textbook", "a secondary source", "an encyclopedia entry"]'::jsonb,0,'It was created at the time.','original'),
('113.41.d.28.D',3,'A textbook chapter about the New Deal is what kind of source?','["a diary", "a secondary source", "a primary source", "an oral history"]'::jsonb,1,'It interprets events after the fact.','original'),
('113.41.d.28.E',4,'A newspaper from 1917 describes German soldiers only in cruel terms. What should a historian consider?','["that all details are neutral", "that the paper is a legal document", "that wartime propaganda may shape the portrayal", "that bias cannot exist"]'::jsonb,2,'Wartime coverage can be biased.','original'),
('113.41.d.28.F',3,'A strong historical claim should include what?','["only dates", "only a quotation", "only opinion", "supporting evidence and reasoning"]'::jsonb,3,'Claims need evidence.','original'),
('113.41.d.29.B',3,'Using the term ''filibuster'' correctly means referring to what?','["a tactic to delay a vote in the Senate", "a voting machine", "a type of tax", "a campaign poster"]'::jsonb,0,'Use social studies terminology accurately.','original'),
('113.41.d.30.A',3,'Which visual would best show how the percentage of immigrants changed over time?','["a recipe", "a line graph", "a pie chart of a single year", "a portrait"]'::jsonb,1,'Line graphs show change over time.','original'),
('113.41.d.30.B',3,'A map shows the highest population density along the coasts. Which question helps a student analyze this pattern?','["''Who printed the map?''", "''What color is the map?''", "''Why do people tend to settle near coasts and rivers?''", "''How wide is the page?''"]'::jsonb,2,'Questions about distribution build analysis.','original'),
('113.41.d.31.A',3,'A mock election in class helps students understand what?','["tax law", "currency exchange", "military strategy", "voting and democratic processes"]'::jsonb,3,'Simulations model civic processes.','original'),
('113.41.d.31.B',3,'In a decision-making process, what step comes right after identifying a problem?','["gathering information", "ignoring options", "writing a conclusion", "announcing a decision"]'::jsonb,0,'Gather information before considering options.','original'),
('113.41.d.12',3,'How did the geography of the Great Plains contribute to the Dust Bowl?','["mountain barriers", "flat, dry land with little tree cover was vulnerable to wind erosion", "heavy rainfall", "ocean winds"]'::jsonb,1,'Geographic conditions amplified the disaster.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
